// retainedBytes models what a string keeps alive in the heap.
const PARENT_LEN = 1000000;
const SLICE_LEN = 12;
const COUNT = 100;

// A SlicedString holds a pointer to its parent -> retains the parent's full length.
function slicedRetained(parentLen) { return parentLen; }
// A forced flat copy ('' + slice) is standalone -> retains only its own length.
function copyRetained(sliceLen) { return sliceLen; }

let leak = 0, fixed = 0;
for (let i = 0; i < COUNT; i++) {
  leak += slicedRetained(PARENT_LEN); // each slice pins a full parent
  fixed += copyRetained(SLICE_LEN);   // each copy keeps only its chars
}
console.log('sliced=' + leak + ' copied=' + fixed);

